mapper.select:
SELECT cm.MESSAGE_ID AS messageId, cm.ROOM_ID AS roomId, cm.SENDER_ID AS senderId, NVL(u.NICKNAME, u.NAME) AS senderName, cm.MESSAGE_TYPE AS messageType, cm.CONTENT AS content, cm.FILE_ID AS fileId, cm.SENT_AT AS sentAt FROM CHAT_MESSAGE cm LEFT JOIN USERS u ON u.USER_ID = cm.SENDER_ID WHERE cm.ROOM_ID = #{roomId} AND cm.DELETED_YN = 'N'
AND cm.MESSAGE_ID < #{beforeMessageId}
ORDER BY cm.MESSAGE_ID ASC FETCH FIRST #{size} ROWS ONLY
